<script type="text/javascript">
    (function () {
        var hopDongProcessingModal = null;

        function getHopDongProcessingModal() {
            var el = document.getElementById('hopDongProcessingModal');
            if (!el || typeof bootstrap === 'undefined' || !bootstrap.Modal) {
                return null;
            }
            if (!hopDongProcessingModal) {
                hopDongProcessingModal = bootstrap.Modal.getOrCreateInstance(el, {
                    backdrop: 'static',
                    keyboard: false
                });
            }
            return hopDongProcessingModal;
        }

        function showHopDongProcessing() {
            var modal = getHopDongProcessingModal();
            if (modal) {
                modal.show();
            }
        }

        function hideHopDongProcessing() {
            var modal = getHopDongProcessingModal();
            if (modal) {
                modal.hide();
            }
        }

        function hookHopDongPageRequestManager() {
            if (typeof Sys === 'undefined' || !Sys.WebForms || !Sys.WebForms.PageRequestManager) {
                return;
            }
            var prm = Sys.WebForms.PageRequestManager.getInstance();
            if (prm.get_isInAsyncPostBack()) {
                showHopDongProcessing();
            }
            prm.add_beginRequest(function () {
                showHopDongProcessing();
            });
            prm.add_endRequest(function () {
                hideHopDongProcessing();
            });
        }

        if (typeof Sys !== 'undefined' && Sys.Application) {
            Sys.Application.add_load(hookHopDongPageRequestManager);
        } else {
            hookHopDongPageRequestManager();
        }
    })();
</script>
